/**
 * REST API endpoint to fetch new form entries for the pipeline engine
 */
function mifeco_register_pipeline_endpoint() {
    register_rest_route('mifeco/v1', '/entries', [
        'methods' => 'GET',
        'callback' => 'mifeco_get_pipeline_entries',
        'permission_callback' => function() {
            // Verify a simple API key
            $key = isset($_GET['api_key']) ? sanitize_text_field($_GET['api_key']) : '';
            $expected = get_option('mifeco_pipeline_api_key', '');
            return !empty($expected) && hash_equals($expected, $key);
        },
    ]);

    register_rest_route('mifeco/v1', '/entries/mark-read', [
        'methods' => 'POST',
        'callback' => 'mifeco_mark_entries_read',
        'permission_callback' => function() {
            $key = isset($_GET['api_key']) ? sanitize_text_field($_GET['api_key']) : '';
            $expected = get_option('mifeco_pipeline_api_key', '');
            return !empty($expected) && hash_equals($expected, $key);
        },
    ]);
}
add_action('rest_api_init', 'mifeco_register_pipeline_endpoint');

function mifeco_get_pipeline_entries() {
    global $wpdb;

    $form_ids = [];
    foreach (['consulting', 'books', 'saas'] as $slug) {
        $id = get_option('mifeco_form_' . $slug);
        if ($id) $form_ids[] = intval($id);
    }

    if (empty($form_ids)) {
        return new WP_REST_Response(['entries' => []], 200);
    }

    $placeholders = implode(',', array_fill(0, count($form_ids), '%d'));

    $results = $wpdb->get_results($wpdb->prepare(
        "SELECT e.entry_id, e.form_id, e.fields, e.date, f.form_title 
         FROM {$wpdb->prefix}wpforms_entries e
         JOIN {$wpdb->prefix}wpforms_forms f ON e.form_id = f.form_id
         WHERE e.form_id IN ($placeholders) AND e.viewed = 0
         ORDER BY e.date DESC
         LIMIT 50",
        $form_ids
    ));

    $entries = [];
    foreach ($results as $row) {
        $fields = json_decode($row->fields, true);
        $entry_data = [
            'entry_id' => $row->entry_id,
            'form_id' => $row->form_id,
            'form_title' => $row->form_title,
            'date' => $row->date,
            'fields' => [],
        ];
        if (is_array($fields)) {
            foreach ($fields as $field) {
                $entry_data['fields'][$field['name']] = $field['value'] ?? '';
            }
        }
        $entries[] = $entry_data;
    }

    return new WP_REST_Response(['entries' => $entries], 200);
}

function mifeco_mark_entries_read() {
    global $wpdb;

    $body = json_decode(file_get_contents('php://input'), true);
    $entry_ids = isset($body['entry_ids']) ? array_map('intval', $body['entry_ids']) : [];

    if (empty($entry_ids)) {
        return new WP_REST_Response(['success' => false, 'message' => 'No entry IDs provided'], 400);
    }

    $placeholders = implode(',', array_fill(0, count($entry_ids), '%d'));
    $wpdb->query($wpdb->prepare(
        "UPDATE {$wpdb->prefix}wpforms_entries SET viewed = 1 WHERE entry_id IN ($placeholders)",
        $entry_ids
    ));

    return new WP_REST_Response(['success' => true, 'updated' => count($entry_ids)], 200);
}
